WITH r AS MATERIALIZED(SELECT f.uuid,f.formname,f.reported,coalesce(f.chw_area,c.doc#>>'{contact,parent,_id}') AS site_uuid,c.doc->'fields' AS fields FROM public.form_metadata f JOIN LATERAL(SELECT doc FROM public.couchdb c WHERE c.doc->>'_id'=f.uuid LIMIT 1) c ON true WHERE f.reported>=date_trunc('month',CURRENT_DATE)-interval '12 months' AND reported<date_trunc('month',CURRENT_DATE) AND f.formname IN ('patient_assessment_under_5','care_of_pregnant_women_and_others','referral_followup_over_5','pregnancy_registration','pregnancy_confirmation','pregnancy_followup','pregnancy_referral_followup','mother_referral_followup','postnatal_followup','delivery_registration','fp_registration','fp_reference_followup','fp_renewal_followup')) SELECT site_uuid AS entity_uuid,date_trunc('month',reported)::date AS reported_month,count(DISTINCT uuid)::numeric AS clinical_visits FROM r WHERE (formname='patient_assessment_under_5' AND (fields#>>'{s_reported,s_reported_how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='care_of_pregnant_women_and_others' AND (fields#>>'{s_reported,s_reported_how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='referral_followup_over_5' AND (fields#>>'{g_realisation,how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='pregnancy_registration' AND (fields#>>'{g_reported,how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='pregnancy_confirmation' AND (fields#>>'{g_reported,how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='pregnancy_followup' AND (fields#>>'{g_followup_realization,g_patient_availability,how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='pregnancy_referral_followup' AND (fields#>>'{g_search_for_woman,how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='mother_referral_followup' AND (fields#>>'{g_followup,g_patient_present,how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='postnatal_followup' AND (fields#>>'{g_realisation,how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='delivery_registration' AND (fields#>>'{g_registration_recording,how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='fp_registration' AND (fields#>>'{g_evaluation,g_patient_found,how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='fp_reference_followup' AND (fields#>>'{g_followup,g_patient_found,how_patient_found}' IN ('home_visit','during_home_visit','vad'))) OR (formname='fp_renewal_followup' AND (fields#>>'{g_followup,g_patient_found,how_patient_found}' IN ('home_visit','during_home_visit','vad'))) GROUP BY 1,2
